CREATE TABLE IF NOT EXISTS aiv_state(id INTEGER PRIMARY KEY CHECK(id=1), schema_version INTEGER NOT NULL, checkpoint INTEGER NOT NULL DEFAULT 0, legacy_ceiling INTEGER NOT NULL, chain_count INTEGER NOT NULL DEFAULT 0, chain_head TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS main_rules(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, condition TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('ALLOW','DENIED','WATCH')), priority INTEGER NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), version INTEGER NOT NULL CHECK(version>0), created_ms INTEGER NOT NULL, UNIQUE(name,version));
CREATE TABLE IF NOT EXISTS decisions(id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL UNIQUE REFERENCES events(id), rule_name TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('ALLOW','DENIED','WATCH')), reason TEXT NOT NULL, timestamp_ms INTEGER NOT NULL, hash_prev TEXT NOT NULL, hash_self TEXT NOT NULL, signature TEXT, enforcement TEXT NOT NULL DEFAULT 'NOT_ENFORCED' CHECK(enforcement='NOT_ENFORCED'));
CREATE TABLE IF NOT EXISTS journal_chain(id INTEGER PRIMARY KEY, event_id INTEGER REFERENCES events(id), hash_prev TEXT NOT NULL CHECK(length(hash_prev)=64), hash_self TEXT NOT NULL CHECK(length(hash_self)=64), signature TEXT, timestamp_ms INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('EVENT','DECISION')), decision_id INTEGER REFERENCES decisions(id), payload TEXT NOT NULL, UNIQUE(event_id,kind));
CREATE TABLE IF NOT EXISTS reference_apps(package_name TEXT NOT NULL, declared_permissions TEXT NOT NULL, certificates TEXT NOT NULL, source TEXT NOT NULL, fetched_ms INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(package_name,source));
CREATE TABLE IF NOT EXISTS sync_state(id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL UNIQUE, last_sync_ms INTEGER, cursor TEXT, status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS decisions_filter ON decisions(decision,id);
CREATE INDEX IF NOT EXISTS decisions_event ON decisions(event_id);
CREATE TRIGGER IF NOT EXISTS aiv_events_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'AIV append-only'); END;
CREATE TRIGGER IF NOT EXISTS aiv_events_update BEFORE UPDATE ON events WHEN OLD.hash_self IS NOT NULL OR NEW.id IS NOT OLD.id OR NEW.timestamp_ms IS NOT OLD.timestamp_ms OR NEW.app IS NOT OLD.app OR NEW.action IS NOT OLD.action OR NEW.destination IS NOT OLD.destination OR NEW.transport IS NOT OLD.transport OR NEW.category IS NOT OLD.category OR NEW.payload IS NOT OLD.payload OR NEW.search_text IS NOT OLD.search_text BEGIN SELECT RAISE(ABORT,'AIV event immutable'); END;
CREATE TRIGGER IF NOT EXISTS aiv_decisions_update BEFORE UPDATE ON decisions BEGIN SELECT RAISE(ABORT,'AIV append-only'); END;
CREATE TRIGGER IF NOT EXISTS aiv_decisions_delete BEFORE DELETE ON decisions BEGIN SELECT RAISE(ABORT,'AIV append-only'); END;
CREATE TRIGGER IF NOT EXISTS aiv_chain_update BEFORE UPDATE ON journal_chain BEGIN SELECT RAISE(ABORT,'AIV append-only'); END;
CREATE TRIGGER IF NOT EXISTS aiv_chain_delete BEFORE DELETE ON journal_chain BEGIN SELECT RAISE(ABORT,'AIV append-only'); END;
CREATE TRIGGER IF NOT EXISTS aiv_rules_update BEFORE UPDATE ON main_rules BEGIN SELECT RAISE(ABORT,'AIV rule version required'); END;
CREATE TRIGGER IF NOT EXISTS aiv_rules_delete BEFORE DELETE ON main_rules BEGIN SELECT RAISE(ABORT,'AIV append-only'); END;
CREATE TABLE IF NOT EXISTS aiv_app_stats(app TEXT PRIMARY KEY, evaluated INTEGER NOT NULL DEFAULT 0, findings INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS aiv_stats_state(id INTEGER PRIMARY KEY CHECK(id=1), checkpoint INTEGER NOT NULL DEFAULT 0, evaluated INTEGER NOT NULL DEFAULT 0, findings INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO aiv_stats_state(id) VALUES(1);